int split(const int *a,int n,int **p,int *c){*p=NULL;*c=0;for(int i=0;i<n;i++)*c+=a[i]<0;if(!*c)return 1;*p=malloc((size_t)*c*sizeof **p);if(!*p)return 0;int k=0;for(int i=0;i<n;i++)if(a[i]<0)(*p)[k++]=a[i];return 1;}int main(void){int n,a[100],*p,c;scanf("%d",&n);for(int i=0;i<n;i++)scanf("%d",a+i);if(!split(a,n,&p,&c))return 1;printf("%d\n",c);if(!c)puts("EMPTY");else{for(int i=0;i<c;i++)printf("%s%d",i?" ":"",p[i]);puts("");}free(p);return 0;}

