typedef struct{int p,q;}Rat;int gcd(int a,int b){return b?gcd(b,a%b):a;}Rat plus(Rat a,Rat b){Rat r={a.p*b.q+b.p*a.q,a.q*b.q};int g=gcd(abs(r.p),r.q);r.p/=g;r.q/=g;return r;}int main(void){Rat a,b,r;scanf("%d%d%d%d",&a.p,&a.q,&b.p,&b.q);r=plus(a,b);printf("%d/%d\n",r.p,r.q);return 0;}

