int *find(int *a,int n,int *len){int *best=NULL,k=0;*len=0;for(int i=0;i<n;i++){k=a[i]>0?k+1:0;if(k>*len){*len=k;best=a+i-k+1;}}return best;}int main(void){int n,a[100],len;scanf("%d",&n);for(int i=0;i<n;i++)scanf("%d",a+i);int *p=find(a,n,&len);printf("%d %d\n",p?(int)(p-a):-1,len);return 0;}

