struct Item{int id,qty;};int apply(struct Item *a,int n,int id,int d){for(int i=0;i<n;i++)if(a[i].id==id){if(a[i].qty+d<0)return 0;a[i].qty+=d;return 1;}return 0;}int main(void){int n,m,bad=0;struct Item a[30];scanf("%d%d",&n,&m);for(int i=0;i<n;i++)scanf("%d%d",&a[i].id,&a[i].qty);for(int i=0,id,d;i<m;i++){scanf("%d%d",&id,&d);bad+=!apply(a,n,id,d);}printf("%d\n",bad);for(int i=0;i<n;i++)printf("%s%d",i?" ":"",a[i].qty);puts("");return 0;}

